def parse_inline(text):
    if text is None:
        text=""
    inlines=[]
    pos=0
    while pos < len(text):
        m_img=None
        m_link=None
        m_code=None
        m_strong=None
        m_em=None
        # image
        mi=re.search(r'!\[([^\]]*)\]\(([^)]+)\)', text[pos:])
        if mi: m_img=mi
        # link (not image)
        for m in re.finditer(r'\[([^\]]+)\]\(([^)]+)\)', text[pos:]):
            s=m.start()
            abs_pos=pos+s
            if abs_pos>0 and text[abs_pos-1]=='!':
                continue
            m_link=m
            break
        mc=re.search(r'`([^`]+)`', text[pos:])
        if mc: m_code=mc
        ms=re.search(r'\*\*([^*]+)\*\*', text[pos:])
        if ms: m_strong=ms
        # em single
        for m in re.finditer(r'\*([^*]+)\*', text[pos:]):
            s=m.start(); e=m.end()
            # check surrounding stars not part of **
            if s>0 and text[pos+s-1]=='*':
                continue
            if pos+e < len(text) and text[pos+e]=='*':
                continue
            m_em=m
            break
        cands=[]
        if m_img: cands.append(('img',m_img))
        if m_link: cands.append(('link',m_link))
        if m_code: cands.append(('code',m_code))
        if m_strong: cands.append(('strong',m_strong))
        if m_em: cands.append(('em',m_em))
        if not cands:
            rem=text[pos:]
            if rem:
                inlines.append({'type':'text','value':rem})
            break
        typ, m = min(cands, key=lambda x: x[1].start())
        s=m.start(); e=m.end()
        if s>0:
            before=text[pos:pos+s]
            if before:
                inlines.append({'type':'text','value':before})
        if typ=='img':
            inlines.append({'type':'image','alt':m.group(1),'src':m.group(2),'title':None})
        elif typ=='link':
            inlines.append({'type':'link','text':m.group(1),'url':m.group(2),'title':None})
        elif typ=='code':
            inlines.append({'type':'code','value':m.group(1)})
        elif typ=='strong':
            inlines.append({'type':'strong','value':m.group(1)})
        elif typ=='em':
            inlines.append({'type':'emphasis','value':m.group(1)})
        pos+=e
    if not inlines:
        inlines.append({'type':'text','value':text})
    return inlines

def parse_blocks(raw):
    if not raw or not raw.strip():
        return []
    lines=raw.splitlines()
    blocks=[]
    i=0; n=len(lines)
    while i<n:
        line=lines[i]
        if not line.strip():
            i+=1; continue
