        if stripped.startswith("```"):
            lang=stripped[3:].strip()
            cont=[]
            i+=1
            while i<n and not lines[i].strip().startswith("```"):
                cont.append(lines[i]); i+=1
            if i<n and lines[i].strip().startswith("```"):
                i+=1
            content="\n".join(cont)
            blocks.append({'type':'code','language':lang,'content':content,'start_line':1,'end_line':1})
            continue
        if '|' in line and i+1<n and re.match(r'^\s*\|?[\s\-\|:\s]+\|?\s*$', lines[i+1]) and '---' in lines[i+1]:
            headers=[h.strip() for h in line.strip().strip('|').split('|')]
            i+=2
            rows=[]
            while i<n and ('|' in lines[i]) and lines[i].strip()!="":
                row=[c.strip() for c in lines[i].strip().strip('|').split('|')]
                rows.append(row); i+=1
            blocks.append({'type':'table','headers':headers,'alignments':['none']*len(headers),'rows':rows})
            continue
        if line.lstrip().startswith('>'):
            bq=[]
            while i<n and lines[i].lstrip().startswith('>'):
                bq.append(re.sub(r'^\s*>\s?','',lines[i])); i+=1
            content=" ".join(bq)
            inner={'type':'paragraph','content':content,'inline':parse_inline(content)}
            blocks.append({'type':'blockquote','content':content,'blocks':[inner]})
            continue
        if re.match(r'^\s*[-*+]\s+', line) or re.match(r'^\s*\d+\.\s+', line):
            items=[]
            ordered=bool(re.match(r'^\s*\d+\.\s+', line))
            while i<n and (re.match(r'^\s*[-*+]\s+', lines[i]) or re.match(r'^\s*\d+\.\s+', lines[i])):
                raw_item=lines[i]
                mcb=re.match(r'^\s*[-*+]\s+\[([xX ])\]\s+(.*)', raw_item)
                if mcb:
                    checked=mcb.group(1).lower()=='x'
