                    items.append({'checked':checked,'content':cont,'inline':parse_inline(cont)})
                else:
                    cont=re.sub(r'^\s*([-*+]|\d+\.)\s+','',raw_item)
                    items.append({'checked':None,'content':cont,'inline':parse_inline(cont)})
                i+=1
            blocks.append({'type':'list','ordered':ordered,'items':items})
            continue
        # paragraph
        para=[]
