def parse_document(content):
    lines=content.splitlines()
    lines_nl=content.splitlines(True)
    byte_offs=[]; off=0
    for ln in lines_nl:
        byte_offs.append(off)
        off+=len(ln.encode('utf-8'))
    total_bytes=off
    headings=[]
    in_code=False
    for idx, raw in enumerate(lines):
        s=raw.lstrip()
        if s.startswith("```"):
            in_code=not in_code
            continue
