            continue
        bq=re.sub(r'^\s*(>\s*)+','', raw)
        m=re.match(r'^ {0,3}(#{1,6})[ \t]+(.*)$', bq)
        if m:
            lvl=len(m.group(1))
            title_raw=m.group(2)
            title=re.sub(r'\s+#+\s*$','',title_raw).strip()
            hl=idx+1
            cs=hl+1
            ho=byte_offs[idx] if idx < len(byte_offs) else total_bytes
            co=byte_offs[idx+1] if idx+1 < len(byte_offs) else total_bytes
            slug=slugify(title) if title else ""
            nid=slug if slug else f"heading-{hl}"
            headings.append({'level':lvl,'title':title,'slug':slug,'id':nid,'position':{'line':cs,'offset':co},'heading_line':hl,'heading_offset':ho,'content_start_line':cs,'content_offset':co,'raw_title':title_raw})
    is_syn=False
    if not headings:
