def parse_document(content):
    lines=content.splitlines()
    lines_nl=content.splitlines(True)
    byte_offs=[]; off=0
    for ln in lines_nl:
        byte_offs.append(off)
        off+=len(ln.encode('utf-8'))
    total_bytes=off
    headings=[]
    in_code=False
    for idx, raw in enumerate(lines):
        s=raw.lstrip()
        if s.startswith("```"):
            in_code=not in_code
            continue
        if in_code:
            continue
        bq=re.sub(r'^\s*(>\s*)+','', raw)
        m=re.match(r'^ {0,3}(#{1,6})[ \t]+(.*)$', bq)
        if m:
            lvl=len(m.group(1))
            title_raw=m.group(2)
            title=re.sub(r'\s+#+\s*$','',title_raw).strip()
            hl=idx+1
            cs=hl+1
            ho=byte_offs[idx] if idx < len(byte_offs) else total_bytes
            co=byte_offs[idx+1] if idx+1 < len(byte_offs) else total_bytes
            slug=slugify(title) if title else ""
            nid=slug if slug else f"heading-{hl}"
            headings.append({'level':lvl,'title':title,'slug':slug,'id':nid,'position':{'line':cs,'offset':co},'heading_line':hl,'heading_offset':ho,'content_start_line':cs,'content_offset':co,'raw_title':title_raw})
    is_syn=False
    if not headings:
        is_syn=True
        headings=[{'level':1,'title':'Input','slug':'input','id':'input','position':{'line':2,'offset':8},'heading_line':1,'heading_offset':0,'content_start_line':2,'content_offset':8}]
    nodes=[]
    for h in headings:
        nodes.append({'id':h['id'],'level':h['level'],'title':h['title'],'slug':h['slug'],'position':h['position'],'heading_line':h['heading_line'],'content_start_line':h['content_start_line'],'content_offset':h['content_offset'],'children':[],'raw':"", 'blocks':[]})
    roots=[]; stack=[]
    for n in nodes:
        while stack and stack[-1]['level'] >= n['level']:
            stack.pop()
        if not stack:
            roots.append(n)
        else:
            stack[-1]['children'].append(n)
        stack.append(n)
    if is_syn:
        raw=content.strip()
        for n in nodes:
            n['raw']=raw
            n['blocks']=parse_blocks(raw)
    else:
        for idx,n in enumerate(nodes):
            if idx+1<len(nodes):
                nxt_hl=nodes[idx+1]['heading_line']
            else:
                nxt_hl=len(lines)+1
            cs=n['content_start_line']
            ce=nxt_hl-1
            if cs>ce or cs>len(lines):
                raw=""
            else:
                raw="\n".join(lines[cs-1:ce]).strip()
            n['raw']=raw
            n['blocks']=parse_blocks(raw)
    maxDepth=max((x['level'] for x in nodes), default=1)
    if is_syn:
        wc=len(("# Input\n"+content).split())
    else:
        wc=len(content.split())
    meta={'source':None,'headingCount':len(nodes),'maxDepth':maxDepth,'wordCount':wc}
    cbl, lks, ims, tbls, lst, bqs = extract_global_elements(content, lines)
    return {'content':content,'lines':lines,'lines_nl':lines_nl,'byte_offs':byte_offs,'total_bytes':total_bytes,'headings':headings,'nodes':nodes,'roots':roots,'metadata':meta,'is_syn':is_syn,'code_blocks':cbl,'links':lks,'images':ims,'tables':tbls,'lists':lst,'blockquotes':bqs}

def get_content(files):
    if not files:
        return SELECT_A_FILE_MD
    first=files[0]
    if first=="-":
        data=sys.stdin.read()
        if data=="":
            eprint("Error reading input: Empty input provided")
            sys.exit(1)
        return data
    if os.path.isdir(first):
        return SELECT_A_FILE_MD
    if not os.path.isfile(first):
        eprint("Error reading input: I/O error: No such file or directory (os error 2)")
        sys.exit(1)
    try:
        with open(first,'r',encoding='utf-8',errors='ignore') as f:
            data=f.read()
    except:
        eprint("Error reading input: I/O error: No such file or directory (os error 2)")
        sys.exit(1)
    return data

def render_heading_list(nodes, filter_pat=None, level=None):
    out=[]
    for h in nodes:
        if level is not None:
            if h['level']!=level:
                continue
        elif filter_pat is not None:
            if filter_pat.lower() not in h['title'].lower():
                continue
        out.append("#"*h['level']+" "+h['title'])
    if out:
        sys.stdout.write("\n".join(out)+"\n")

def render_tree(roots):
    def rec(node,prefix,is_last):
        conn="└──" if is_last else "├──"
        line=prefix+conn+"#"*node['level']+" "+node['title']
        lines=[line]
        child_pref=prefix+("   " if is_last else "│  ")
        for idx,ch in enumerate(node['children']):
            last=idx==len(node['children'])-1
            lines.extend(rec(ch, child_pref, last))
        return lines
    all_lines=[]
    for idx, r in enumerate(roots):
        last=idx==len(roots)-1
        all_lines.extend(rec(r,"",last))
    if all_lines:
        sys.stdout.write("\n".join(all_lines)+"\n")

def render_count(doc):
    cnts={}
    for n in doc['nodes']:
        cnts[n['level']]=cnts.get(n['level'],0)+1
    sys.stdout.write("Heading counts:\n")
    for lvl in sorted(cnts):
        sys.stdout.write(f"  {'#'*lvl}: {cnts[lvl]}\n")
    sys.stdout.write("\n")
    sys.stdout.write(f"Total: {len(doc['nodes'])}\n")

def render_section(doc, name):
    target=None; idx_target=-1
    low=name.lower()
    for idx, n in enumerate(doc['nodes']):
        if n['title'].lower()==low:
            target=n; idx_target=idx; break
    if not target:
        for idx,n in enumerate(doc['nodes']):
            if low in n['title'].lower():
                target=n; idx_target=idx; break
    if not target:
        eprint(f"Section '{name}' not found")
        sys.exit(1)
    lines=doc['lines']
    start=target['heading_line']
    lvl=target['level']
    end=len(lines)+1
    for j in range(idx_target+1,len(doc['nodes'])):
        nxt=doc['nodes'][j]
        if nxt['level']<=lvl:
            end=nxt['heading_line']
            break
    slice_lines=lines[start-1:end-1]
    out="\n".join(slice_lines).strip()
    if out:
        sys.stdout.write(out+"\n")
    else:
        sys.stdout.write("#"*lvl+" "+target['title']+"\n")

