    # handle >> first to avoid confusion with >
    if ">>" in selector_str:
        left,right=selector_str.split(">>",1)
        left=left.strip(); right=right.strip()
        left_res=evaluate_selector(left, doc)
        right_res=evaluate_selector(right, doc)
        # descendant logic
        # Build parent map for headings
        parent_map={}
        stack=[]
        for node in doc['nodes']:
            while stack and stack[-1]['level'] >= node['level']:
                stack.pop()
            if stack:
                parent_map[node['id']] = stack[-1]['id']
            else:
                parent_map[node['id']] = None
            stack.append(node)
        def is_desc(child_id, anc_id):
            cur=parent_map.get(child_id)
            while cur:
                if cur==anc_id:
                    return True
                cur=parent_map.get(cur)
            return False
        def enclosing_for_line(line_no):
            encl=None
            for h in doc['nodes']:
                if h['heading_line'] <= line_no:
                    encl=h
                else:
                    break
            return encl
        filtered=[]
        for cand in right_res:
            cand_is_h=cand.get('type')=='heading'
            cand_id=cand.get('id')
            cand_line=cand.get('line')
            for anc in left_res:
                anc_id=anc.get('id')
                if not anc_id:
                    continue
                if cand_is_h:
                    if is_desc(cand_id, anc_id):
                        filtered.append(cand); break
                else:
                    encl=enclosing_for_line(cand_line or 0)
                    if encl and (encl['id']==anc_id or is_desc(encl['id'], anc_id)):
                        filtered.append(cand); break
        return filtered
    if ">" in selector_str:
        # ensure not part of >> already handled, now single >
        left,right=selector_str.split(">",1)
        left=left.strip(); right=right.strip()
        if left=="" or right=="":
            return []
        left_res=evaluate_selector(left, doc)
        right_res=evaluate_selector(right, doc)
        # direct child
        parent_map={}
        stack=[]
        for node in doc['nodes']:
            while stack and stack[-1]['level'] >= node['level']:
                stack.pop()
            if stack:
                parent_map[node['id']] = stack[-1]['id']
            else:
                parent_map[node['id']]=None
            stack.append(node)
        def enclosing_for_line(line_no):
            encl=None
            for h in doc['nodes']:
                if h['heading_line'] <= line_no:
                    encl=h
                else:
                    break
            return encl
        filtered=[]
        for cand in right_res:
            cand_is_h=cand.get('type')=='heading'
            cand_id=cand.get('id')
            cand_line=cand.get('line')
            for anc in left_res:
                anc_id=anc.get('id')
                if not anc_id:
                    continue
                if cand_is_h:
                    if parent_map.get(cand_id)==anc_id:
                        filtered.append(cand); break
                else:
                    encl=enclosing_for_line(cand_line or 0)
                    if encl and encl['id']==anc_id:
                        filtered.append(cand); break
        return filtered
    # simple selector
    # Check for array wrapper like "[.h]" ? That's not selector but collection wrapper. However our evaluate_selector might be called with "[.h]" from split_pipes? The first segment could be "[.h]". We handle that later in evaluation.
    # But if selector_str is like "[.h]" itself, handle unwrapping
    if selector_str.startswith("[") and selector_str.endswith("]"):
        inner=selector_str[1:-1].strip()
        # inner should be selector like ".h" or ".h2"
        return evaluate_selector(inner, doc)
    m=re.match(r'^\.([A-Za-z0-9]+)(?:\[(.*)\])?$', selector_str)
    if not m:
        return []
    elem=m.group(1)
    bracket=m.group(2)
    base=get_elements_for_tag(elem, doc)
    if bracket is None:
        return base
    inside=bracket.strip()
    # slice check
    if ":" in inside:
        parts=inside.split(":")
        if len(parts)!=2:
            return []
        a_str=parts[0].strip(); b_str=parts[1].strip()
        def parse_idx(s):
            if s=="":
                return None
            try:
                return int(s)
            except:
                return None
        a=parse_idx(a_str) if a_str!="" else None
        b=parse_idx(b_str) if b_str!="" else None
        return base[a:b]
    if re.match(r'^-?\d+$', inside):
