    if (inside.startswith('"') and inside.endswith('"')) or (inside.startswith("'") and inside.endswith("'")):
        exact=inside[1:-1]
        res=[]
        for item in base:
            txt=item.get('text') or item.get('title') or ""
            if txt==exact:
                res.append(item)
        return res
    if inside.lower()=="external" and elem.lower() in ('link','a'):
        res=[it for it in base if it.get('link_type')=='external']
        return res
    # code language fuzzy
    if elem.lower()=='code':
        res=[]
        for item in base:
            lang=item.get('language') or ""
            if lang.lower()==inside.lower() or inside.lower() in lang.lower():
                res.append(item)
        return res
    # fuzzy heading contains
    lower_inside=inside.lower()
    res=[]
    for item in base:
        txt=item.get('text') or item.get('title') or item.get('content') or ""
        if lower_inside in txt.lower():
            res.append(item)
    return res

