def parse_func_args(arg_str):
    args=[]
    cur=""
    in_single=False; in_double=False
    depth=0
    for ch in arg_str:
        if ch=="'" and not in_double:
            in_single=not in_single
            cur+=ch
            continue
        if ch=='"' and not in_single:
            in_double=not in_double
            cur+=ch
            continue
        if in_single or in_double:
            cur+=ch
            continue
        if ch=='(':
            depth+=1; cur+=ch; continue
        if ch==')':
            depth-=1; cur+=ch; continue
        if ch==',' and depth==0:
            args.append(cur.strip())
            cur=""
            continue
        cur+=ch
    if cur.strip()!="":
        args.append(cur.strip())
    return args

