def format_item_for_json(item, doc):
    if isinstance(item, dict):
        # Determine type
        if item.get('type')=='heading':
            return {'type':'heading','level':item.get('level'),'text':item.get('text'),'line':item.get('line')}
        if item.get('type')=='code':
            # need language, content, start_line, end_line? Original for code had language, content, start_line, end_line? But query json for code had type code, language, content, start_line, end_line maybe?
            # Let's see earlier query json for code: had type, language, content, start_line, end_line? For /tmp/q.md .code query, we had language python etc with start_line 1? Actually for full list json we got start_line 1 etc.
            # We'll provide similar.
            return {'type':'code','language':item.get('language'),'content':item.get('content'),'start_line':item.get('line') or item.get('start_line') or 1,'end_line':item.get('line') or item.get('end_line') or 1}
        if item.get('type')=='link':
            return {'type':'link','text':item.get('text'),'url':item.get('url'),'link_type':item.get('link_type'),'line':item.get('line')}
        if item.get('type')=='image':
            return {'type':'image','alt':item.get('alt'),'src':item.get('src'),'title':item.get('title'),'line':item.get('line')}
        if item.get('type')=='table':
            return {'type':'table','headers':item.get('headers'),'rows':item.get('rows'),'alignments':item.get('alignments'),'line':item.get('line')}
        if item.get('type')=='list':
            return {'type':'list','ordered':item.get('ordered'),'items':item.get('items'),'line':item.get('line')}
        if item.get('type')=='blockquote':
            return {'type':'blockquote','content':item.get('content'),'line':item.get('line')}
        # For generic dict already in json shape (like stats grouping), return as is
        if 'type' not in item and any(k in item for k in ('headings','code_blocks','words')):
            return item
        # fallback: return item as is but remove internal keys
        out={k:v for k,v in item.items() if not k.startswith('_')}
        return out
    elif isinstance(item, str):
        return item
    elif isinstance(item, (int,float)):
        return item
    elif isinstance(item, list):
        return [format_item_for_json(x, doc) for x in item]
    else:
        return str(item)

def item_to_plain(item, doc):
    if isinstance(item, dict):
        t=item.get('type')
        if t=='heading':
            return "#"*item.get('level',1)+" "+item.get('text','')
        if t=='code':
            lang=item.get('language') or ""
            content=item.get('content') or ""
            if lang:
                return f"```{lang}\n{content}\n```"
            else:
                return f"```\n{content}\n```"
        if t=='link':
            txt=item.get('text') or ""
            url=item.get('url') or ""
            return f"[{txt}]({url})"
        if t=='image':
            alt=item.get('alt') or ""
            src=item.get('src') or ""
            return f"![{alt}]({src})"
        if t=='table':
            headers=item.get('headers') or []
            rows=item.get('rows') or []
            # render simple
            header_line="| " + " | ".join(headers) + " |"
            sep="| " + " | ".join(["---"]*len(headers)) + " |"
            row_lines=["| " + " | ".join(r) + " |" for r in rows]
            return "\n".join([header_line, sep] + row_lines)
        if t=='list':
            its=item.get('items') or []
            lines=[]
            for it in its:
                checked=it.get('checked')
                content=it.get('content') or ""
                if checked is True:
                    lines.append(f"- [x] {content}")
                elif checked is False:
                    lines.append(f"- [ ] {content}")
                else:
                    lines.append(f"- {content}")
            return "\n".join(lines)
        if t=='blockquote':
            return "> " + item.get('content','')
        # For document etc?
        if 'text' in item:
            return str(item['text'])
        if 'content' in item:
            return str(item['content'])
        return json.dumps(item)
    elif isinstance(item, str):
        return item
    elif isinstance(item, (int,float)):
        # For floats that are integers, strip .0?
        if isinstance(item,float) and item.is_integer():
            return str(int(item))
        return str(item)
    elif isinstance(item, list):
        return json.dumps(item)
    else:
        return str(item)

def item_to_md(item, doc):
    if isinstance(item, dict):
        t=item.get('type')
        if t=='heading':
            # For heading md, we want full markdown section? For query md output for heading, they output heading section including content? Example: -q '.h' --query-output md gave "# Title\n## Section A\ncontent ..." Actually earlier md output for .h gave the whole markdown for each heading section? Check: for /tmp/filter.md -q '.h' --query-output md gave "# Apple\n\n## Banana\n\n..." Each heading separated. So for plain heading md, we output heading markdown (level + text) plus ??? For filter.md, heading raw empty, so md gave heading lines.
